.platform-row {
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
    align-items: center;
    margin-bottom:30px;
}

.platform-col {
    flex: 0 0 auto;
    width: fit-content;
    border: 1px solid #ddd;
    border-radius: 6px;
    overflow: hidden;
    transition: all 0.3s ease;
}

.platform-col a {
    display: block;
    padding: 10px 16px;
    color: #fff;
    text-decoration: none;
    font-size: 15px;
    font-weight: 600;
    line-height: 1.2;
    transition: all 0.3s ease;
}

/* Hover */
.platform-col:hover {
    border-color: var(--primary);
    transform: translateY(-2px);
    box-shadow: 0 4px 10px rgba(0, 0, 0, 0.08);
}

.platform-col:hover a {
    color: var(--primary);
}

/* Mobile */
@media (max-width: 576px) {
    .platform-row {
        gap: 8px;
    }

    .platform-col a {
        padding: 8px 12px;
        font-size: 14px;
    }
}
